<?php
declare(strict_types=1);namespace Vendi\Payments;use PDO;use RuntimeException;
final class PaymentMethodService{public function __construct(private PDO $db){}
 public function available(int$b,int$branch):array{$q=$this->db->prepare("SELECT pm.id,pm.code,pm.name,pm.type,pm.affects_cash_drawer,pm.allows_change,pm.requires_reference,pm.quick_compatible,pm.is_quick_default FROM payment_methods pm LEFT JOIN branch_payment_methods bpm ON bpm.payment_method_id=pm.id AND bpm.branch_id=? WHERE pm.business_id=? AND pm.active=1 AND COALESCE(bpm.enabled,1)=1 ORDER BY pm.sort_order,pm.name");$q->execute([$branch,$b]);return$q->fetchAll();}
 public function quickDefault(int$b,int$branch):?array{foreach($this->available($b,$branch) as$m)if((int)$m['quick_compatible']===1&&(int)$m['requires_reference']===0&&(int)$m['is_quick_default']===1)return$m;foreach($this->available($b,$branch) as$m)if((int)$m['quick_compatible']===1&&(int)$m['requires_reference']===0)return$m;return null;}
 public function configure(int$b,int$branch,int$id,array$d):void{$q=$this->db->prepare("SELECT id FROM payment_methods WHERE id=? AND business_id=? LIMIT 1");$q->execute([$id,$b]);if(!$q->fetchColumn())throw new RuntimeException('Método de pago no encontrado.');$quick=!empty($d['is_quick_default']);$requires=!empty($d['requires_reference']);if($quick&&$requires)throw new RuntimeException('El método rápido no puede exigir referencia.');$this->db->beginTransaction();try{if($quick)$this->db->prepare("UPDATE payment_methods SET is_quick_default=0 WHERE business_id=?")->execute([$b]);$this->db->prepare("UPDATE payment_methods SET affects_cash_drawer=?,allows_change=?,requires_reference=?,quick_compatible=?,is_quick_default=? WHERE id=? AND business_id=?")->execute([!empty($d['affects_cash_drawer']),!empty($d['allows_change']),$requires,!empty($d['quick_compatible']),$quick,$id,$b]);$this->db->prepare("INSERT INTO branch_payment_methods(branch_id,payment_method_id,enabled) VALUES(?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled)")->execute([$branch,$id,!empty($d['enabled'])]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function create(int$b,string$code,string$name,string$type):int{if(!in_array($type,['cash','card','transfer','credit','other'],true))throw new RuntimeException('Tipo inválido.');$q=$this->db->prepare("INSERT INTO payment_methods(business_id,code,name,type) VALUES(?,?,?,?)");$q->execute([$b,$code,$name,$type]);return(int)$this->db->lastInsertId();}}
